def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    times = sorted({t for start, end, _ in jobs for t in (start, end)})
    if not times:
        return 0

    index = {t: i for i, t in enumerate(times)}
    n = len(times)
    graph = [[] for _ in range(n)]

    for i in range(n - 1):
        graph[i].append([i + 1, k, 0])

    for start, end, pay in jobs:
        graph[index[start]].append([index[end], 1, -pay])

    total_cost = 0

    for _ in range(k):
        dist = [float("inf")] * n
        parent = [None] * n
        dist[0] = 0

        for u in range(n):
            if dist[u] == float("inf"):
                continue
            for edge_i, edge in enumerate(graph[u]):
                v, cap, cost = edge
                if cap > 0 and dist[v] > dist[u] + cost:
                    dist[v] = dist[u] + cost
                    parent[v] = (u, edge_i)

        if dist[-1] >= 0:
            break

        total_cost += dist[-1]
        v = n - 1
        while v != 0:
            u, edge_i = parent[v]
            edge = graph[u][edge_i]
            edge[1] -= 1
            graph[v].append([u, 1, -edge[2]])
            v = u

    return -total_cost
